import base64
import re
import os

b64_html = b""
b64_js1 = b"        "
b64_html2 = b"                    "
b64_js2 = b""

def run():
    c1 = open("templates/company.html", "r", encoding="utf-8").read()
    if "summary-total" not in c1:
        c1 = re.sub(r'(<div id="ext-finance-dashboard">\s*<div style="display: flex;.*?</button>\s*</div>)', r'\g<1>\n' + base64.b64decode(b64_html).decode("utf-8"), c1, flags=re.DOTALL)
        open("templates/company.html", "w", encoding="utf-8").write(c1)

    c2 = open("static/js/main.js", "r", encoding="utf-8").read()
    if "summary-total" not in c2:
        c2 = c2.replace("function renderInquiryList(data) {", "function renderInquiryList(data) {\n" + base64.b64decode(b64_js1).decode("utf-8"))
        open("static/js/main.js", "w", encoding="utf-8").write(c2)

    c3 = open("templates/master.html", "r", encoding="utf-8").read()
    if "exportAdminInquiry" not in c3:
        c3 = re.sub(r'<button class="btn-logout" onclick="loadAdminInquiryStatus\(\)"[^>]*>새로고침</button>', base64.b64decode(b64_html2).decode("utf-8"), c3)
        open("templates/master.html", "w", encoding="utf-8").write(c3)

    c4 = open("static/js/main.js", "r", encoding="utf-8").read()
    if "promptUpdateDetail" not in c4:
        c4 = c4 + "\n" + base64.b64decode(b64_js2).decode("utf-8")
        c4 = c4.replace('<button class="btn-logout" style="padding:4px 8px; width:auto; font-size:0.8rem;" onclick="viewInquiryHistory(${item.id})">이력</button>',
                        '<button class="btn-logout" style="padding:4px 8px; width:auto; font-size:0.8rem;" onclick="viewInquiryHistory(${item.id})">이력</button><button class="btn-submit" style="padding:4px 8px; width:auto; font-size:0.8rem; margin-left:5px;" onclick="promptUpdateDetail(${item.id})">수정</button>')
        open("static/js/main.js", "w", encoding="utf-8").write(c4)

    print("Success")

if __name__ == '__main__':
    run()
